255	                        + " WHERE channel_id = ? AND business_day = ?"
256	                        + " ORDER BY published_version DESC LIMIT 1",
257	                PUBLICATION_MAPPER, channelId, Date.valueOf(businessDay)).stream().findFirst();
258	    }
