51	@Service
52	public class PlayoutService {
53	
54	    /** 业务时区。 */
55	    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
56	
57	    private static final String OP_REPLACE_DRAFT = "REPLACE_DRAFT";
58	    private static final String OP_PUBLISH = "PUBLISH";
59	    private static final String OP_REVOKE_GRANT = "REVOKE_GRANT";
60	
61	    private final PlayoutRepository repo;
62	    private final ObjectMapper objectMapper;
63	
64	    public PlayoutService(PlayoutRepository repo, ObjectMapper objectMapper) {
65	        this.repo = repo;
66	        this.objectMapper = objectMapper;
67	    }
68	
69	    // ---------- 素材 ----------
70	
71	    /** 创建素材；id 为空时生成稳定 ID。 */
72	    @Transactional
73	    public AssetResponse createAsset(CreateAssetRequest request) {
74	        String id = request.id() == null || request.id().isBlank()
75	                ? UUID.randomUUID().toString() : request.id();
76	        try {
77	            repo.insertAsset(id, request.durationMs(), nowMs());
78	        } catch (DuplicateKeyException e) {
79	            throw ApiException.conflict("DUPLICATE_ID", "素材 ID 已存在: " + id);
80	        }
81	        return new AssetResponse(id, request.durationMs());
82	    }
83	
84	    // ---------- 频道 ----------
85	
86	    /** 创建频道，保底素材必须已存在且不会被撤销。 */
87	    @Transactional
88	    public ChannelResponse createChannel(CreateChannelRequest request) {
89	        String id = request.id() == null || request.id().isBlank()
90	                ? UUID.randomUUID().toString() : request.id();
91	        if (repo.findAsset(request.fallbackAssetId()).isEmpty()) {
92	            throw ApiException.notFound("保底素材不存在: " + request.fallbackAssetId());
93	        }
94	        try {
95	            repo.insertChannel(id, request.fallbackAssetId(), nowMs());
96	        } catch (DuplicateKeyException e) {
97	            throw ApiException.conflict("DUPLICATE_ID", "频道 ID 已存在: " + id);
98	        }
99	        return new ChannelResponse(id, request.fallbackAssetId());
100	    }
101	
102	    // ---------- 授权 ----------
103	
104	    /** 创建授权，关联频道与普通素材，有效区间左闭右开。 */
105	    @Transactional
106	    public GrantResponse createGrant(CreateGrantRequest request) {
107	        var channel = repo.findChannel(request.channelId())
108	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + request.channelId()));
109	        if (repo.findAsset(request.assetId()).isEmpty()) {
110	            throw ApiException.notFound("素材不存在: " + request.assetId());
111	        }
112	        long fromMs = toMs(request.validFrom());
113	        long toMs = toMs(request.validTo());
114	        if (toMs <= fromMs) {
115	            throw ApiException.badRequest("授权有效区间终点必须大于起点");
116	        }
117	        if (channel.fallbackAssetId().equals(request.assetId())) {
118	            throw ApiException.unprocessable("FALLBACK_ASSET_NOT_GRANTABLE",
119	                    "保底素材无需授权，不能对其创建授权");
120	        }
121	        long id = repo.insertGrant(request.channelId(), request.assetId(), fromMs, toMs, nowMs());
122	        return new GrantResponse(id, request.channelId(), request.assetId(),
123	                request.validFrom(), request.validTo(), false);
124	    }
125	
126	    /** 撤销授权；幂等：同 requestId 同参数返回原结果，改参数返回 409。 */
127	    @Transactional
128	    public GrantResponse revokeGrant(long grantId, String requestId) {
129	        String hash = sha256(OP_REVOKE_GRANT + "|" + grantId);
130	        return idempotent(requestId, OP_REVOKE_GRANT, hash, GrantResponse.class, () -> {
131	            GrantRow grant = repo.findGrant(grantId)
132	                    .orElseThrow(() -> ApiException.notFound("授权不存在: " + grantId));
133	            int updated = repo.revokeGrant(grantId, requestId, nowMs());
134	            if (updated == 0) {
135	                throw ApiException.conflict("GRANT_ALREADY_REVOKED", "授权已撤销: " + grantId);
136	            }
137	            return new GrantResponse(grant.id(), grant.channelId(), grant.assetId(),
138	                    atMs(grant.validFromMs()), atMs(grant.validToMs()), true);
139	        });
140	    }
