        String p = prefix();
        String channel = newChannelWithGrant(p);
        long grantId = lastGrantId;
        putJson("/api/channels/" + channel + "/drafts/" + DAY,
                        replaceDraftBody("req-" + p + "-d1", 0,
                                segment(p + "seg-1", p + "movie", T_10, T_11)))
