    // ---------- 素材分级声明 ----------

    @Test
    void assetRatingDeclaredOrDefaulted() throws Exception {
        String p = prefix();

        // 声明分级
        postJson("/api/assets", Map.of("id", p + "g", "durationMs", 1000, "rating", "G"))
                .andExpect(status().isOk())
