    @Test
    void publishOutsideWindowUnrestrictedAndBoundaryMinutes() throws Exception {
        String p = prefix();
        String channel = newChannelWithRatedAssets(p);

        // 管控时段仅覆盖 10:00-11:00（含起点不含终点）
